contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount to deposit into C to create recorded credit
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure we can send the requested depositAmount in this test
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // require a meaningful deposit amount (we want to observe positive credit)
        require(depositAmount > 0, "depositAmount must be > 0");

        // record C's external balance before deposit
        uint cBal_before = address(c).balance;

        // make the deposit to establish credit[msg.sender] for this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // after deposit, C's balance should have increased by depositAmount
        uint cBal_afterDeposit = address(c).balance;
        // record the C balance immediately before withdrawAll
        uint cBal_beforeWithdraw = cBal_afterDeposit;

        // call withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record C balance after the withdraw attempt
        uint cBal_after = address(c).balance;

        // The contract C offers a public behavior: withdrawAll should not allow C's balance to decrease by more than
        // the recorded credit this test created (which is at most depositAmount). We assert that either withdrawAll reverted,
        // or the decrease in C's balance is <= depositAmount.
        // Note: We use cBal_beforeWithdraw and cBal_after which are observable.
        assert(reverted || cBal_beforeWithdraw - cBal_after <= depositAmount);
    }

    receive() external payable { }
}

